"""Close the finite telemetry/error review; all writes are audit documentation."""
from pathlib import Path
from collections import Counter
import json
from merge_finite_batch import BASE, OUT, SRC, HEAD, digest, dump, merge_batch

def ev(path,a,b,reason):
    assert 1<=a<=b<=len((SRC/path).read_text().splitlines())
    return dict(path=path,line_start=a,line_end=b,sha256=digest(SRC/path),baseline_sha=HEAD,origin='source',reason=reason)

findings=[
    dict(id='R2-INF-040',title='Falha de leitura da telemetria aparece como sistema com bom desempenho',severity='P2',classification='novo',baseline_sha=HEAD,area_extension='finite_telemetry_error_batch',
        description='A queryFn lança o error do SDK, mas AdminTelemetriaPage não consome error/isError/status. Sem dados prévios, o default rows=[] chega à tabela quando a primeira consulta terminou em falha. TelemetryTable usa somente isLoading e rows.length e exibe uma mensagem explícita de bom desempenho, enquanto os cards mostram zero erros e média 0ms.',
        consumer_chain=['NavigationService autoriza view telemetry para admin','ViewRouter verifica acesso e monta AdminTelemetriaPage','useQuery recebe rejeição da leitura query_telemetry','Página descarta estado de erro e passa rows=[]/isLoading=false','Tabela anuncia bom desempenho'],
        preconditions=['Usuário com acesso à view de telemetria.', 'Consulta inicial falha depois das tentativas configuradas e não há dados de sucesso no cache dessa chave; não há configuração externa que faça throwOnError.'],
        effect='Uma indisponibilidade ou erro de autorização/consulta é apresentada como ausência de consultas lentas e bom desempenho, justamente quando a tela deveria comunicar que não conseguiu medir. O achado não depende de números reais do banco nem afirma exposição a usuários sem acesso.',
        evidence=[ev('src/pages/AdminTelemetriaPage.tsx',37,59,'Estado de erro omitido; queryFn lança SDK error'),ev('src/pages/AdminTelemetriaPage.tsx',70,98,'Cards calculados do array vazio'),ev('src/pages/AdminTelemetriaPage.tsx',145,148,'Contador e tabela sem estado de erro'),ev('src/pages/admin-telemetria/TelemetryTable.tsx',13,28,'Sem dados vira mensagem explícita de bom desempenho'),ev('src/lib/queryClient.ts',9,25,'Configura retries, mas não eleva todo erro de query à ErrorBoundary'),ev('src/pages/ViewRouter.tsx',81,87,'View telemetry é consumidor ativo'),ev('src/pages/ViewRouter.tsx',129,151,'Gate de acesso presente antes da montagem'),ev('src/services/navigation.service.ts',142,155,'Telemetria restrita por papel no mapa de navegação')],
        acceptance=['Consumir e apresentar falha da query, separada de carregamento, sucesso vazio e sucesso com registros.','Não derivar saúde do sistema de ausência de dados por falha; se houver dados de cache, sinalizar atualização falha/defasagem.','Verificar falha inicial, sucesso vazio, sucesso com alertas e falha de refetch; manter os gates de acesso e o erro já validado pelo cleanup.'],
        affected_tasks=[],probe_ids=['INF-TE-P01'],related_previous_findings=['R2-INF-026'],novelty_basis='Outro consumidor e mecanismo: este SDK error é lançado corretamente e o erro é perdido na apresentação de useQuery, não nas checagens de saúde de Diagnostics.',proof_type='STATIC_AND_BOUNDED_SYNTHETIC_OFFLINE',
        limitations=['Nenhuma query de produto, biblioteca React/TanStack, browser ou retry real executado.','Probe usa o queryFn real com SDK sintético e fornece o estado de erro documentado à fronteira do hook; testa as decisões de página/tabela reais.','A classe de severidade e o limite de 500 registros não foram convertidos em defeitos adicionais.'],
        external_references=[dict(url='https://tanstack.com/query/latest/docs/framework/react/guides/queries',retrieved_on='2026-10-04',source_kind='primary_documentation',supports='Query com falha é distinguida por isError/status e error; a ausência de dados não equivale a sucesso vazio.')]),
    dict(id='R2-INF-041',title='ErrorBoundary ignora fallback nulo usado para retirar overlays com falha',severity='P2',classification='novo',baseline_sha=HEAD,area_extension='finite_telemetry_error_batch',
        description='O contrato de Props aceita fallback ReactNode, mas render verifica seu valor por truthiness. Quando App fornece fallback={null} para os providers diferidos, a condição é falsa e o boundary renderiza a tela padrão de erro, com min-h-screen e role=alert. App documenta expressamente que esse fallback deve retirar silenciosamente a camada opcional.',
        consumer_chain=['App mantém AppRoutes fora do boundary de overlays','DeferredProviders/DeferredHooks são filhos de ErrorBoundary fallback=null','Uma falha chega ao estado hasError','render ignora o fallback explícito null e retorna a UI padrão'],
        preconditions=['O boundary de overlays da aplicação captura uma falha e permanece em hasError.', 'O fallback fornecido é null, como no consumidor atual; para chunk load, após a recuperação automática não ser possível ou já ter sido usada.'],
        effect='Uma falha de componente opcional produz um painel de erro com altura mínima de uma viewport e anúncio assertivo em vez de desaparecer. AppRoutes continua fora e montado; não se afirma que o roteamento ou toda a aplicação foi derrubado. A ocupação visual foi confirmada como classe/JSX, não medida em navegador.',
        evidence=[ev('src/components/errors/ErrorBoundary.tsx',8,13,'Fallback é ReactNode opcional'),ev('src/components/errors/ErrorBoundary.tsx',129,142,'if truthy ignora null e cai na UI padrão'),ev('src/App.tsx',15,24,'Contrato de recuperação silenciosa dos overlays'),ev('src/App.tsx',128,143,'Consumidor real fornece null e mantém AppRoutes fora do boundary')],
        acceptance=['Distinguir fallback não fornecido de fallback fornecido como null/false/zero/string vazia; retornar o ReactNode explícito.','Verificar erro com fallback=null, fallback customizado e ausência de fallback, além do caminho sem erro.','Manter os wrappers de sessionStorage, limitação de autoreload e isolamento de AppRoutes; validar em browser que a camada opcional desaparece sem deslocar a aplicação.'],
        affected_tasks=[],probe_ids=['INF-TE-P02'],related_previous_findings=[],novelty_basis='Contrato produtivo específico de fallback nulo; diferente da simples presença de ErrorBoundary em imports ou dos retries de UI genérica.',proof_type='STATIC_AND_BOUNDED_SYNTHETIC_OFFLINE',
        limitations=['Probe chama o método render real isolado, com DEV=false e JSX inerte; não executa componentDidCatch, reportClientError ou reload.','O comentário de main.tsx sobre um wrapper não montado foi tratado pelo root como observação; não compõe este achado.','Os controles de chunk recovery e ocultação de detalhes em produção foram lidos e preservados.'])
]

