inventory=[]
for path,(note,ranges) in sorted(notes.items()):
    p=SRC/path;n=len(p.read_text().splitlines());ranges=ranges or [[1,n]]
    assert all(1<=a<=b<=n for a,b in ranges)
    full=ranges==[[1,n]]
    inventory.append(dict(path=path,sha256=digest(p),bytes=p.stat().st_size,lines=n,baseline_sha=HEAD,reviewed_ranges=ranges,review_level='semantic' if full else 'targeted',full_file_read=full,primary_delegated=path in primary,layer='telemetry_error_delegated' if path in primary else 'telemetry_error_support',review_basis=note))
